waves.point_eqs_eel:
//Alle Funktionen muessen rel. zu t_rel sein

k1 = cos(time/3);
k2 = sin(time/2);

t_abs = sample;
t_rel = sample-time/2.12;
ampl =  cos(t_rel)*5; 
//ampl = 3;

ox = sin (t_rel*8) + ampl*sin (t_rel*12) ;
oy = cos (t_rel*13) + ampl*cos (t_rel*11);
oz =  ampl/3;




//r = sqr(sin(t_rel*3.4));
//g = sqr(sin(t_rel*2.3));
//b = sqr (cos(t_rel*1.9));

r = 1;
g = 0.5;
b = 0;

a=0.25*(cos(t_abs*3.14/2)) + 0.2 *below (abs(1-t_abs- t1),0.0);
//a=0.25*(sin(t_abs*3.14)) + 0.4 *below (abs(1-t_abs-t1), bass_att/1);
a=0.25*(cos(t_abs*1.5)) + 0.7 *below (abs(t_abs),0.0);

xang = k1*3;
yang = 1;
zang = 3*k1;
fov = 0.22;

monitor = t2;

// Rotation um x,y,z

mx = ox*cos(zang) - oy*sin(zang);
my = ox*sin(zang) + oy*cos(zang);

ox = mx;
oy = my;
mx = ox*cos(yang) + oz*sin(yang);
mz = - ox*sin(yang) + oz*cos(yang);
ox = mx;
oz = mz;
my = oy*cos(xang) - oz*sin(xang);
mz = oy*sin(xang) + oz*cos(xang);
oy = my;
oz = mz;

oz = oz - 6;
x = ox*fov/oz +0.5;
//x = (x-.5)*0.75 + 0.5;
y = oy*fov/oz + 0.5;

preset.frame_eqs_eel:
dec_med = pow (0.9, 30/fps);
dec_slow = pow (0.99, 30/fps);
beat = max (max (bass, mid), treb); 
avg = avg*dec_slow + beat*(1-dec_slow);
is_beat = above(beat, .5+avg+peak) * above (time, t0+.2);
t0 = is_beat*time + (1-is_beat)*t0;
peak = is_beat * beat + (1-is_beat)*peak*dec_med;
index = (index + is_beat) %2;
index2 = (index2 + is_beat*bnot(index))%2;
index3 = (index3 + is_beat*bnot(index)*bnot(index2))%3;


q20 = avg;
q21 = beat;
q22 = peak;
q23 = index;
q24 = is_beat;
q26 = bass + mid + treb;

//k1 =  is_beat*bnot(index)*bnot(index2);

k1 =  is_beat*equal(index,0);
p1 =  k1*(p1+1) + (1-k1)*p1;
p2 = dec_med * p2+ (1-dec_med)*p1;
rott = p2 * 3.14159265359/2;
q1 = cos(rott);

q27 = index;
q28 = index2 -.5;
//**************************


rot = .0*q27;;
dy = .01 * sin(time/7);;
dx = .01 * sin(time/4);;
zoom = 1.2;

